import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), [ (k,len(v),len(v[0])) for k,v in G.items()])

def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    specials=[c for c in cnt if c!=bg]
    out=[row[:] for row in grid]
    for c in specials:
        cells=[(i,j) for i in range(h) for j in range(w) if grid[i][j]==c]
        js={j for _,j in cells}
        # border side: colors on grid edge
        if any(j==0 for _,j in cells) and any(j==w-1 for _,j in cells): side='both'
        elif any(j==0 for _,j in cells): side='left'
        elif any(j==w-1 for _,j in cells): side='right'
        else: side=None
        others=[s for s in specials if s!=c]
        if side in ('left','right') and others:
            fill=others[0]
            for i in range(h):
                bj=0 if side=='left' else w-1
                if grid[i][bj]!=c: continue
                step=1 if side=='left' else -1
                j=bj+step
                while 0<=j<w and grid[i][j]==bg:
                    out[i][j]=fill; j+=step
                if 0<=j<w and grid[i][j]!=c and grid[i][j]!=bg:
                    # interior special (of other color) or run of border color? handle run of specials
                    run=[]
                    jj=j
                    while 0<=jj<w and grid[i][jj]==grid[i][j]:
                        run.append(jj); jj+=step
                    out[i][run[-1]]=4
                    for jj2 in run[:-1]: out[i][jj2]=fill
    return out

